let nodes=template().map(n=>({...n,x:n.x*1.35+80,y:n.y*.75+20})),state=[],tick=0,source=null,history=new DraftHistory();try{const saved=localStorage.getItem('fillout-pcb-reference-draft-v1');if(saved)nodes=validateDraft(JSON.parse(saved));}catch{}
