function viewScale(){return parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--studio-scale'))||1;}
function wirePath(p,n,i){const x=p.x+128,y=p.y+53,tx=n.x,ty=n.y+50+i*24,mid=tx>x?Math.round((x+tx)/2/8)*8:x+32+i*16;if(tx>x)return 'M'+x+','+y+' H'+mid+' V'+ty+' H'+tx;const bottom=Math.max(y,ty)+70+i*16;return 'M'+x+','+y+' H'+mid+' V'+bottom+' H'+(tx-32)+' V'+ty+' H'+tx;}
