<div class="palette-examples"><label for="example">${t('Borrow a starting point','从示例开始')}</label><select id="example"><option value="">${t('Choose example','选择示例')}</option><option value="nand">Quote / NAND</option><option value="not">NOT</option><option value="memory">Settle / Memory</option></select><p class="hint">${t('Examples replace your draft. Export first to keep it.','示例会替换草稿，请先导出保留。')}</p></div>
